def is_sparkly(n):
    # Function to find the smallest divisor greater than 1
    def smallest_divisor_greater_than_1(x):
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return i
        return x  # if no divisor found, x is a prime number

    # Function to count the total number of divisors
    def count_divisors(n):
        divisors = set()
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)
        return len(divisors)

    # Function to check if smallest divisor is equal to total number of divisors
    return smallest_divisor_greater_than_1(n) == count_divisors(n)

