# Function to check if a graph is Eulerian
def is_eulerian(vertices):
    degree = {v: 0 for v in vertices}
    for v in vertices:
        for w in edges:
            if v in w:
                degree[v] += 1
    for d in degree.values():
        if d % 2 != 0:
            return False
    return True

# Function to find all possible ways to choose one or more edges
def find_all_ways(vertices):
    total_ways = 0
    n = len(vertices)

    # Each vertex has 2 edges
    for mask in range(2**n):
        count = 0
        for i in range(n):
            if (mask >> i) & 1:
                count += 1
        if count >= 1:
            total_ways += 1

    return total_ways

