# Define the function to check if a number has exactly b distinct prime divisors
def has_b_distinct_prime_divisors(b):
    n = b**5
    # Function to find the number of distinct prime divisors of n
    def count_distinct_prime_factors(n):
        factors = set()
        for i in range(2, int(sp.sqrt(n)) + 1):
            if n % i == 0:
                factors.add(i)
                while n % i == 0:
                    n //= i
        if n > 1:
            factors.add(n)
        return len(factors)

    return count_distinct_prime_factors(n) == b

